os.makedirs(output_folder, exist_ok=True)

for i in carreras:
    response = requests.get(f'{baseUrl}{carreras[i]}')

    if response.status_code!=200:
        print(f"Error al descargar el archivo para {i}. Código de estado: {response.status_code}")
